package gitrepo

import (
	"testing"
)

// Hook creation utilities for common test scenarios.

// WithGommitlintHook adds a gommitlint commit-msg hook to the repository.
func (r *TestRepo) WithGommitlintHook() *TestRepo {
	r.t.Helper()

	hookContent := `#!/bin/sh
# Generated by gommitlint
gommitlint validate --message-file "$1"`

	return r.WithHook("commit-msg", hookContent)
}

// WithCustomHook adds a custom commit-msg hook to the repository.
func (r *TestRepo) WithCustomHook() *TestRepo {
	r.t.Helper()

	hookContent := `#!/bin/sh
echo "Custom hook validation"
exit 0`

	return r.WithHook("commit-msg", hookContent)
}

// Factory functions for common hook test scenarios.

// NewRepoForHooks creates a minimal repository suitable for hook testing.
// This creates just the .git structure without requiring actual commits.
func NewRepoForHooks(t *testing.T) *TestRepo {
	t.Helper()

	return NewEmptyRepo(t)
}

// NewRepoWithGommitlintHook creates a repository with a gommitlint hook already installed.
func NewRepoWithGommitlintHook(t *testing.T) *TestRepo {
	t.Helper()

	return NewRepoForHooks(t).WithGommitlintHook()
}

// NewRepoWithCustomHook creates a repository with a custom hook installed.
func NewRepoWithCustomHook(t *testing.T) *TestRepo {
	t.Helper()

	return NewRepoForHooks(t).WithCustomHook()
}
